from django.utils import timezone


# Versions whose obligations were extracted before the stamp
# existed count as extracted — a report must not pay for a
# second extraction of the same text
def stamp_extracted(apps, schema_editor):
    Version = apps.get_model("corpus", "LegalDocumentVersion")
    Obligation = apps.get_model("corpus", "Obligation")
    extracted = Obligation.objects.filter(source_kind="legal").exclude(version=None).values_list(
        "version_id", flat=True).distinct()
    Version.objects.filter(id__in=list(extracted)).update(obligations_extracted_at=timezone.now())


